('GestiStock — SaaS de gestion', 'SaaS & App', 'MVP SaaS de gestion de stock pour commerces, multi-boutiques.', 'MVP livré en 8 semaines', '/images/service-saas.jpg', 3, 1),
('Tok Tok Livraison — app mobile', 'SaaS & App', 'Application de livraison avec suivi en temps réel et paiement mobile.', '5 000+ livraisons suivies', '/images/project-delivery.jpg', 4, 1),
