INSERT INTO testimonials (name, role, text, initials, sort_order, active) VALUES
('Aïcha N.', 'Fondatrice, boutique de mode — Douala', 'Ma boutique en ligne a été livrée en 3 semaines, paiement Mobile Money inclus. Mes ventes ont doublé dès le deuxième mois.', 'AN', 0, 1),
('Serge M.', 'Gérant de restaurant — Bonapriso', 'Enfin une agence qui parle simplement ! Prix annoncé = prix payé. Ma page reçoit des réservations tous les jours.', 'SM', 1, 1),
('Clarisse T.', 'Consultante indépendante — Yaoundé', 'Site vitrine élégant, livré rapidement, et l''équipe reste disponible sur WhatsApp quand j''ai une question. Je recommande.', 'CT', 2, 1),
('Jean-Paul K.', 'Directeur, PME logistique — Douala', 'Notre outil de suivi sur-mesure a remplacé trois fichiers Excel. L''équipe a vraiment compris notre métier avant de coder.', 'JK', 3, 1),
('Mireille B.', 'Coach & formatrice — Bafoussam', 'J''avais un petit budget, ils ont trouvé une formule adaptée sans sacrifier la qualité. Le digital accessible, c''est vrai.', 'MB', 4, 1),
('Éric F.', 'Startup fintech — Douala', 'Le MVP de notre SaaS est sorti en 6 semaines. Code propre, bonne archi, on a levé nos premiers fonds avec cette démo.', 'EF', 5, 1),
('Nadège E.', 'ONG locale — Limbé', 'Site multilingue, don en ligne, formation de notre équipe : tout était compris. Un vrai partenaire, pas juste un prestataire.', 'NE', 6, 1),
('Boris A.', 'Agence immobilière — Bonamoussadi', 'Nos annonces sont en ligne en deux clics et les clients nous trouvent sur Google. Meilleur investissement de l''année.', 'BA', 7, 1),
('Sandrine P.', 'Pâtisserie artisanale — Akwa', 'Ils ont créé une identité qui me ressemble et un site aussi gourmand que mes gâteaux. Les commandes arrivent via le site !', 'SP', 8, 1);
